# backend/agent/kernel package. Generated by scripts/kernel_split_check.py (init-package / move).
# Readers of the kernel's source for tests and scripts. Stdlib only; imports no kernel module.
#   kernel_source()          the facade text followed by every kernel/**/*.py text (except
#                            __init__.py), sorted by path. Text mode: universal newlines.
#   kernel_tree()            ONE ast.Module equivalent to the pre-split agent_kernel.py: each file is
#                            parsed on its own; the facade module is the base; the bodies of every
#                            *Mixin class are appended to its `class AgentKernel`; the other
#                            module-level nodes of the kernel files are appended to the module body
#                            (`from __future__` lines and the Mixin classes themselves are skipped).
#                            The facade's generated <kernel-split:...> blocks (re-exports, the
#                            _PROPAGATE shim) and the Mixin bases of AgentKernel are dropped, so the
#                            tree has the structure of the pre-split module.
#                            Node linenos stay those of their own file: only comparable within one
#                            function. With no moved module ast.dump(kernel_tree()) equals
#                            ast.dump(ast.parse(<agent_kernel.py text>)).
#   kernel_function_source(name)
#                            ast.get_source_segment text of the ONE def called `name` (any depth,
#                            from whichever file holds it). Raises LookupError for 0 or >1 defs.
import ast
import os


def _kernel_paths():
    here = os.path.dirname(os.path.abspath(__file__))
    paths = [os.path.join(os.path.dirname(here), "agent_kernel.py")]
    found = []
    for dirpath, dirnames, filenames in os.walk(here):
        dirnames[:] = sorted(d for d in dirnames if d != "__pycache__")
        found.extend(os.path.join(dirpath, f) for f in filenames
                     if f.endswith(".py") and f != "__init__.py")
    paths.extend(sorted(found, key=lambda q: os.path.relpath(q, here).replace(os.sep, "/")))
    return paths


def kernel_source(encoding="utf-8", errors="replace") -> str:
    parts = []
    for path in _kernel_paths():
        with open(path, "r", encoding=encoding, errors=errors) as fh:
            text = fh.read()
        parts.append(text if (not text or text.endswith("\n")) else text + "\n")
    return "".join(parts)


def _parse(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        text = fh.read()
    return text, ast.parse(text, filename=path)


def _generated_ranges(text):
    out, start = [], None
    for i, line in enumerate(text.split(chr(10)), 1):
        if line.startswith("# <kernel-split:"):
            start = i
        elif line.startswith("# </kernel-split:") and start:
            out.append((start, i))
            start = None
    return out


def kernel_tree() -> ast.Module:
    paths = _kernel_paths()
    text, base = _parse(paths[0])
    gen = _generated_ranges(text)
    base.body = [n for n in base.body if not any(a <= n.lineno <= b for a, b in gen)]
    cls = next(n for n in base.body if isinstance(n, ast.ClassDef) and n.name == "AgentKernel")
    cls.bases = [b for b in cls.bases if not (isinstance(b, ast.Name) and b.id.endswith("Mixin"))]
    for path in paths[1:]:
        _, tree = _parse(path)
        for node in tree.body:
            if isinstance(node, ast.ImportFrom) and node.module == "__future__":
                continue
            if isinstance(node, ast.ClassDef) and node.name.endswith("Mixin"):
                cls.body.extend(node.body)
                continue
            base.body.append(node)
    return base


def kernel_function_source(name: str) -> str:
    hits = []
    for path in _kernel_paths():
        text, tree = _parse(path)
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name:
                hits.append((path, text, node))
    if len(hits) != 1:
        raise LookupError("kernel function %r: %d definitions found (want exactly 1): %s" % (
            name, len(hits), [h[0] for h in hits]))
    _, text, node = hits[0]
    return ast.get_source_segment(text, node) or ""
